<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Service\Visibility\ThemeAssetVisibilityService;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeAssetRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeAssetVisibilityService $visibility,
        private readonly ThemeAssetReadGateway $reader
    ) {
    }

    public function allowRetrieve(?ThemeAssetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Theme asset");
        $span = $this->startSpan("Check allow of retrieve usecase for Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?ThemeAssetRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Theme asset");
        $span = $this->startSpan("Check hidden fields usecase for Theme asset");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): ThemeAssetRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Theme asset");
        $span = $this->startSpan("Run retrieve usecase for Theme asset");
        try {
            $ref = new ThemeAssetRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Theme asset');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ThemeAssetRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveContent(string $uid): BinaryContent
    {
        $this->logDebug("Run retrieve Content file usecase for Theme asset");
        $span = $this->startSpan("Run retrieve Content file usecase for Theme asset");
        try {
            $ref = new ThemeAssetRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve content of Theme asset');
            }
            if (!$visible = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $url = $visible->getContent();
            if (null === $url) {
                throw new NotFoundException($uid);
            }
            return $this->reader->readContent($url);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
